//! 🧪️ Paged SQLite text retains the actual prefix after original receipt refusal.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
use semio_framework_value::NativeEncodeControl;
use semio_framework_value_testing_admission::{OriginalConstructionAuthority,OriginalWorkAuthority};
#[path="../🧪️support.rs"]
mod support;
use support::{Work,Recipient,close,settle};
struct Chunks(Vec<String>);impl Utf8Text for Chunks{fn text_bytes(&self)->usize{self.0.iter().map(String::len).sum()}fn text_chunk_count(&self)->usize{self.0.len()}fn text_chunk(&self,index:usize)->Option<&str>{self.0.get(index).map(String::as_str)}}
fn refusing(refused:std::sync::Arc<std::sync::atomic::AtomicBool>,grant:RetainedCloneGrant)->Recipient<impl FnMut(RetainedCloneProgress)->Result<(),ValueError>+Send>{Recipient{grant,submitted:Default::default(),refuse:move|progress:RetainedCloneProgress|if progress.copied_bytes==3&&!refused.swap(true,std::sync::atomic::Ordering::SeqCst){Err(ValueError::literal(ValueRefusalKind::WorkLimit,"paged text receipt refused"))}else{Ok(())}}}
#[test]fn paged_text_preserves_original_prefix_on_receipt_refusal(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(f["chunks"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().to_owned()).collect());assert_eq!(source.text_bytes(),f["bytes"].as_u64().unwrap()as usize);assert_eq!(serde_json::to_string(f["expected"].as_str().unwrap()).unwrap(),serde_json::to_string(&source.0.concat()).unwrap());
 let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let refused=std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));let mut construction=OriginalConstructionAuthority::new(refusing(refused.clone(),grant));let mut work_authority=OriginalWorkAuthority::new(Work(1024));let mut native_progress=|_|true;let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
 let turn=construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|{let mut owner=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut owner);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))})))).unwrap().unwrap().unwrap();
 assert!(refused.load(std::sync::atomic::Ordering::SeqCst));let failure=match turn.result{Err(error)=>error,Ok(())=>panic!("paged receipt unexpectedly accepted")};assert!(marker.performed);assert_eq!(output,f["refusedPrefix"].as_str().unwrap());assert_eq!(output.capacity(),f["bytes"].as_u64().unwrap()as usize);assert_eq!(construction.inspect(|recipient|recipient.submitted),RetainedCloneProgress{copied_items:3,copied_bytes:std::mem::size_of::<String>()+output.len(),retained_capacity_bytes:output.capacity(),released_bytes:0});assert_eq!(turn.work,Some(3));close(output,grant);close(failure,grant);settle(&mut allocation);close(allocation,grant);
}

#[test]fn paged_text_prework_denial_keeps_native_ownership_empty(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(f["chunks"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().to_owned()).collect());let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let refused=std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));let mut construction=OriginalConstructionAuthority::new(refusing(refused.clone(),grant));let mut work_authority=OriginalWorkAuthority::new(Work(f["deniedWork"].as_u64().unwrap()));let mut native_progress=|_|true;let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
 let turn=construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))})))).unwrap().unwrap().unwrap();
 let failure=match turn.result{Err(error)=>error,Ok(())=>panic!("paged work denial unexpectedly accepted")};assert_eq!(turn.work,Some(0));assert_eq!(native.owned_bytes(),0);assert_eq!(output.capacity(),0);assert!(!marker.performed);assert!(!refused.load(std::sync::atomic::Ordering::SeqCst));close(output,grant);close(failure,grant);settle(&mut allocation);close(allocation,grant);
}

#[test]fn empty_paged_chunks_use_original_work_without_fabricated_backing(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(vec![String::new();f["emptyChunks"].as_u64().unwrap()as usize]);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let refused=std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));let mut construction=OriginalConstructionAuthority::new(refusing(refused.clone(),grant));let mut work_authority=OriginalWorkAuthority::new(Work(1024));let mut native_progress=|_|true;let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
 let turn=construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))})))).unwrap().unwrap().unwrap();
 assert!(matches!(turn.result,Ok(())));assert_eq!(turn.work,Some(u128::from(f["emptyWork"].as_u64().unwrap())));assert_eq!(output.capacity(),0);assert_eq!(construction.inspect(|recipient|recipient.submitted),RetainedCloneProgress::default());assert_eq!(native.owned_bytes(),0);close(output,grant);
}

#[test]fn paged_text_decode_direction_posts_exact_original_receipts(){
 use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(f["chunks"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().to_owned()).collect());let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let mut construction=OriginalConstructionAuthority::new(Recipient{grant,submitted:Default::default(),refuse:|_:RetainedCloneProgress|Ok(())});let mut work_authority=OriginalWorkAuthority::new(Work(1024));let mut native_progress=|_|true;let mut native=NativeDecodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Decode(Default::default());
 let turn=construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotDecodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Decode(&mut original);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))})))).unwrap().unwrap().unwrap();
 assert!(matches!(turn.result,Ok(())));assert_eq!(turn.work,Some(3));assert_eq!(output,f["expected"].as_str().unwrap());assert_eq!(construction.inspect(|recipient|recipient.submitted),RetainedCloneProgress{copied_items:3,copied_bytes:std::mem::size_of::<String>()+output.len(),retained_capacity_bytes:output.capacity(),released_bytes:0});assert_eq!(serde_json::to_string(&output).unwrap(),serde_json::to_string(f["expected"].as_str().unwrap()).unwrap());close(output,grant);
}

#[test]fn paged_source_unwind_retains_output_and_stage_receipt(){
 struct PanicChunks;impl Utf8Text for PanicChunks{fn text_bytes(&self)->usize{5}fn text_chunk_count(&self)->usize{2}fn text_chunk(&self,index:usize)->Option<&str>{if index==0{Some("ab")}else{panic!("paged fixture unwind")}}}
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=PanicChunks;let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let refused=std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));let mut construction=OriginalConstructionAuthority::new(refusing(refused.clone(),grant));let mut work_authority=OriginalWorkAuthority::new(Work(1024));let mut native_progress=|_|true;let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let initial=control.allocation_remaining_bytes();let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
 let caught=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))}))));}));
 assert!(caught.is_err());std::mem::forget(construction);std::mem::forget(work_authority);assert_eq!(output,f["unwindPrefix"].as_str().unwrap());assert_eq!(output.capacity(),f["bytes"].as_u64().unwrap() as usize);assert_eq!(initial-control.allocation_remaining_bytes(),output.capacity());let stage=stage_unwind.take().unwrap();assert!(stage.result.is_ok());assert_eq!(stage.work,Some(u128::from(f["unwindWork"].as_u64().unwrap())));close(output,grant);close(stage,grant);
}

#[test]fn paged_text_wrong_allocation_direction_refuses_before_effect(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(vec!["x".into()]);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:64,maximum_release_bytes:64,maximum_depth:4};let mut progress=|_|true;let mut native=NativeEncodeControl::new(64,&mut progress);let mut sql=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Decode(Default::default());let mut stage_unwind=None;let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(&mut native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);
 let turn=copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1);let failure=match turn.result{Err(error)=>error,Ok(())=>panic!("wrong direction accepted")};assert_eq!(turn.work,Some(u128::from(f["wrongDirectionWork"].as_u64().unwrap())));assert_eq!(output.capacity(),0);assert!(!marker.performed);drop(owner);drop(original);assert_eq!(native.owned_bytes(),0);let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};close(failure,close_grant);close(allocation,close_grant);
}

#[test]fn paged_text_unsettled_allocation_refuses_before_effect(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(Vec::new());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:64,maximum_release_bytes:64,maximum_depth:4};let mut progress=|_|true;let mut native=NativeEncodeControl::new(64,&mut progress);let mut sql=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut state=semio_framework_io_control::NativeSnapshotEncodeAllocation::default();state.state.actual=Some(1);let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(state);let mut stage_unwind=None;let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(&mut native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);
 let turn=copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1);let failure=match turn.result{Err(error)=>error,Ok(())=>panic!("occupied allocation accepted")};assert_eq!(turn.work,Some(u128::from(f["occupiedWork"].as_u64().unwrap())));assert!(allocation.is_unsettled());assert_eq!(output.capacity(),0);assert!(!marker.performed);drop(owner);drop(original);assert_eq!(native.owned_bytes(),0);let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};close(failure,close_grant);close(allocation,close_grant);
}
